PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('student','admin')),name TEXT NOT NULL,password TEXT,verified INTEGER NOT NULL DEFAULT 0,student_id TEXT DEFAULT '',phone TEXT DEFAULT '',UNIQUE(email,kind));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verification(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_states(token TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS content(id TEXT PRIMARY KEY,type TEXT NOT NULL,data TEXT NOT NULL,updated TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS content_type ON content(type);
CREATE TABLE IF NOT EXISTS inventory(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>=0),image TEXT DEFAULT '',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS loans(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),item_id TEXT NOT NULL REFERENCES inventory(id),qty INTEGER NOT NULL CHECK(qty>0),start_date TEXT NOT NULL,end_date TEXT NOT NULL,purpose TEXT NOT NULL,affiliation TEXT DEFAULT '',attachment TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','returned')),reason TEXT DEFAULT '',created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),event_id TEXT NOT NULL,position TEXT NOT NULL,note TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reason TEXT DEFAULT '',created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,event_id,position));
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,mime TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('private','public')));
CREATE TABLE IF NOT EXISTS integration_log(id INTEGER PRIMARY KEY CHECK(id=1),last_sync TEXT,error TEXT);
